import json
from pathlib import Path
R=Path(__file__).resolve().parents[2]
bank=json.loads((R/'data/americas.json').read_text()); cov=json.loads((R/'research/americas-coverage.json').read_text())
new=[]; reviews={}
def add(y,n,d,topic,subs,statement,reason,solution=None,page=None,shared=None):
 u=f'https://web.evanchen.cc/exams/JMO-{y}-notes.pdf'; su=u+(f'#page={page}' if page else '')
 reviews.setdefault(y,{})[str(n)]={'difficulty':d,'ratingReason':reason,'sourceUrl':u}
 if shared:
  r=next(p for p in bank if p['id']==shared)
  apps=r.setdefault('appearances',[{k:r[k] for k in ['country','competition','year','number']}])
  a=dict(country='United States',competition='USAJMO',year=y,section='Day 1' if n<4 else 'Day 2',number=str(n),sourceUrl=u)
  if not any(x.get('competition')=='USAJMO' and x.get('year')==y and str(x.get('number'))==str(n) for x in apps): apps.append(a)
  if solution:r['solution']=solution;r['solutionKind']='original-exposition'
  return
 if not 4<=d<=7:return
 new.append(dict(id=f'us-usajmo-{y}-{n}',country='United States',competition='USAJMO',year=y,section='Day 1' if n<4 else 'Day 2',number=str(n),statement=statement,solution=solution or f'[Read Evan Chen’s worked solution, Problem {n}]({su}).',sourceUrl=u,solutionUrl=su,solutionKind='original-exposition' if solution else 'source-link',topic=topic,tags=subs,subtopics=subs,difficulty=d,ratingReason=reason,reviewStatus='individually-assessed',notes='Statement restated in original wording. Author-maintained solution notes, not an official MAA solution publication.'))
add(2010,1,4.5,'Number Theory',['Squares & powers','Factorials & binomial coefficients'],r'Let $P(n)$ count permutations $(a_1,\ldots,a_n)$ of $1,\ldots,n$ with $ka_k$ a square for every $k$. Determine the smallest $n$ for which $2010\mid P(n)$.','Separate integers by squarefree part: admissible permutations act independently on each class. The product of factorials then reduces the threshold to the prime factor 67 of 2010.',page=3)
add(2010,2,4.5,'Algebra',['Sequences & recurrences'],r'For an integer $n>1$, classify increasing positive integer sequences $x_1<\cdots<x_{n-1}$ such that $x_i+x_{n-i}=2n$, and every sum $x_i+x_j<2n$ is another term of the sequence (allow $i=j$).','Adding the smallest term to all but the largest produces exactly as many distinct terms as there are available larger terms. Matching these in order forces an arithmetic progression.',page=4)
add(2010,3,5,'Geometry',[],None,'Same Simson-line and cyclic-quadrilateral argument as USAMO 2010 Q1.',shared='us-usamo-2010-1')
add(2010,4,4.5,'Geometry',['Coordinates & vectors','Constructions & loci'],r'For each integer $n\ge0$, construct three distinct integer-coordinate points on $y=x^2$ whose triangle has area $(2^n m)^2$ for some odd integer $m$.','A symmetric pair of parabola points gives area a(b²−a²). Choosing a power of two and using consecutive odd factors turns the area into the required square; n=0 needs its own small example.',page=7)
add(2010,5,4,'Combinatorics',['Pigeonhole principle','Permutations & arrangements'],r'Prove that there is a family of $1006$ permutations of $1,\ldots,2010$ such that every permutation agrees with some family member in at least one position.','Rotate 1006 values through the first 1006 positions. Pigeonhole guarantees that every permutation has one of those values in that block; the creative step is choosing a block larger than half.',page=8)
add(2010,6,4.5,'Geometry',[],None,'Same incentre-angle and irrational cosine-rule contradiction as USAMO 2010 Q4.',shared='us-usamo-2010-4')
add(2011,1,2.5,'Number Theory',[],None,'Even exponents fail modulo 3 and odd exponents at least 3 fail modulo 4; n=1 is checked directly.')
add(2011,2,5,'Algebra',[],None,'Same homogenization and product-one AM–GM argument as USAMO 2011 Q1.',shared='us-usamo-2011-1')
add(2011,3,6.5,'Geometry',['Coordinates & vectors','Constructions & loci','Projective geometry & conics'],r'At each point $(a,a^2)$ draw the line of slope $2a$. Choose three distinct such points whose three lines bound an equilateral triangle. Determine the locus of that triangle’s centre.','Intersecting pairs of tangents identifies the orthocentre on the directrix. The harder half is proving every point is attained: equality of centroid and orthocentre yields a cubic, and sign changes establish three distinct real roots.',page=5)
add(2011,4,5,'Combinatorics',['Recurrences & generating functions','Induction'],r'Define words $W_0=a$, $W_1=b$, and $W_n=W_{n-2}W_{n-1}$ for $n\ge2$, with juxtaposition denoting concatenation. Show that $W_1W_2\cdots W_n$ is a palindrome for each $n\ge1$.','Reverse the shorter concatenation by induction, then use the Fibonacci concatenation to expose a palindrome surrounded by a word and its reverse. Choosing the right shorter indices is essential.',page=7)
add(2011,5,6,'Geometry',['Circles & tangency','Projective geometry & conics'],r'Five points $A,B,C,D,E$ lie on a circle. An external point $P$ satisfies $PB,PD$ tangent to the circle, $P,A,C$ collinear, and $DE\parallel AC$. Prove that $BE$ passes through the midpoint of $AC$.','The two tangents give a harmonic quadrilateral, and projection from E sends D to the point at infinity, forcing the midpoint. An elementary complex-coordinate alternative requires several linked chord identities.',page=8)
add(2011,6,5.5,'Number Theory',[],None,'Same exponent reduction and n=25 counterexample as USAMO 2011 Q4.',shared='us-usamo-2011-4')
add(2012,1,4.5,'Geometry',['Power of a point & radical axes','Circles & tangency'],r'In triangle $ABC$, choose $P\in AB$, $Q\in AC$ with $AP=AQ$. Distinct $S,R\in BC$ occur in the order $B,S,R,C$ and satisfy $\angle BPS=\angle PRS$ and $\angle CQR=\angle QSR$. Prove $P,Q,R,S$ concyclic.','Interpret the angle conditions as tangent-chord relations. A has equal powers to the circles PRS and QRS, yet is off their proposed radical axis RS; hence those circles coincide.',page=3)
add(2012,2,5.5,'Algebra',[],None,'Same sorted-square Fibonacci-growth argument as USAMO 2012 Q1.',shared='us-usamo-2012-1')
add(2012,3,5.5,'Algebra',['Inequalities'],r'Prove, for positive $a,b,c$, that $\frac{a^3+3b^3}{5a+b}+\frac{b^3+3c^3}{5b+c}+\frac{c^3+3a^3}{5c+a}\ge\frac23(a^2+b^2+c^2)$.','Split the cyclic numerator into two sums, multiply numerator and denominator to create fourth powers, and apply Cauchy separately. Bounding the two new denominators by six times the square sum is the key rearrangement.',page=6)
add(2012,4,4.5,'Number Theory',['Floors & fractional parts'],r'On a circle of circumference 1, start at $P_1$ and repeatedly move counterclockwise through an irrational distance $\alpha\in(0,1)$ to obtain $P_2,\ldots,P_n$, where $n\ge3$. If the two neighbours of $P_n$ among these points are $P_a,P_b$, prove $a+b\le n$.','Assuming a+b>n produces the earlier index a+b−n. Its angular displacement is the sum of the two opposite signed neighbour displacements, so it lies strictly inside their empty arc, a contradiction.',page=8)
add(2012,5,5.5,'Number Theory',['Modular arithmetic','Divisibility & GCD'],r'For distinct $a,b\in\{1,\ldots,2011\}$, let $f(a,b)$ count $k\in\{1,\ldots,2011\}$ for which $ak$ has a larger remainder modulo 2012 than $bk$. Find the least possible $f(a,b)$.','Pair invertible residues k and 2012−k to get the lower bound φ(2012)/2=502. Attaining it requires the less obvious pair a=4,b=1010, for which all non-units contribute nothing.',page=9)
add(2012,6,6.5,'Geometry',[],None,'Same reflected-ray Menelaus argument as USAMO 2012 Q5.',shared='us-usamo-2012-5')
add(2013,1,4.5,'Number Theory',['Modular arithmetic','Squares & powers'],r'Can integers $a,b$ make both $a^5b+3$ and $ab^5+3$ perfect cubes? Justify the answer.','Modulo 9, multiples of 3 are eliminated first. Otherwise each shifted cube forces a residue in {5,7}; multiplying contradicts the sixth-power residue 1. Combining the two congruences is the key step.',page=3)
add(2013,2,5,'Combinatorics',['Bijections','Combinatorial geometry'],r'Fill an $m\times n$ board with nonnegative integers. Side-adjacent entries differ by at most 1, and every entry no larger than all its neighbours is zero. How many such fillings are possible?','A filling is uniquely determined by its nonempty zero set: each entry must equal its shortest grid distance to that set. Both inequalities require proof, using bounded adjacent differences and descending paths.',page=4)
add(2013,3,6,'Geometry',[],None,'Same Miquel point and spiral similarity argument as USAMO 2013 Q1.',shared='us-usamo-2013-1')
add(2013,4,5.5,'Combinatorics',['Recurrences & generating functions','Parity'],r'Let $f(n)$ count ordered expressions of $n$ as a sum of powers of 2; thus $f(4)=6$. Find the smallest integer $n>2013$ such that $f(n)$ is odd.','The first-summand recurrence leads to the pattern n=2^j−1. Its parity induction counts representations of n+1 as two powers of two: unequal summands pair, while equal summands occur once.',solution=r'''Set $f(0)=1$. Splitting by the first summand gives $f(n)=\sum_{2^j\le n}f(n-2^j)$. We prove by induction that $f(n)$ is odd exactly when $n=2^k-1$ for some $k\ge0$. Under the induction hypothesis, the parity of the right side is the number of ordered pairs $(j,k)$ of nonnegative integers satisfying $n+1=2^j+2^k$. Pairs with $j\ne k$ cancel in pairs modulo 2; a diagonal pair exists exactly when $n+1$ is a power of two. This proves the claim, including the base $n=0$. The first such $n$ above 2013 is $2^{11}-1=2047$.''',page=6)
add(2013,5,5.5,'Geometry',['Trigonometry','Angles & cyclic quadrilaterals'],r'Points $X,A,B,Y$ lie in that order on a semicircle with diameter $XY$. Put $P=AY\cap BX$, and let $Z$ be the foot from $P$ to $XY$. Choose $C$ on the semicircle so that $XC\perp AZ$, and put $Q=AY\cap XC$. Prove $BY/XP+CY/XQ=AY/AX$.','A cyclic quadrilateral converts the perpendicular condition into an angle sum. Two sine-rule computations then turn the requested ratio identity into the cosine subtraction formula.',page=7)
fix=r'''Write $x=1+a,y=1+b,z=1+c$ and reorder so $0\le a\le b\le c$. Put $S=\sqrt b+\sqrt c$. The equation is $\sqrt{(1+a)(1+(1+b)(1+c))}=\sqrt a+S$. Since $1+bc\ge2\sqrt{bc}$, we have $(1+b)(1+c)\ge S^2$. Also
$$ (1+a)(1+S^2)-(\sqrt a+S)^2=(\sqrt a S-1)^2\ge0. $$
Thus equality is possible exactly when $bc=1$ and $\sqrt a(\sqrt b+\sqrt c)=1$. Writing $c=t^2$ with $t\ge1$ gives $b=t^{-2}$ and $a=(t+t^{-1})^{-2}$; these satisfy $a\le b\le c$ and the original equation. Therefore the solutions are all permutations of
$$\left(1+\frac{t^2}{(t^2+1)^2},\ 1+t^{-2},\ 1+t^2\right),\qquad t\ge1.$$
'''
add(2013,6,6.5,'Algebra',[],None,'Same equality classification as USAMO 2013 Q4. Independently repaired the cached source’s reversed inequality signs and missing square in the intermediate equality condition.',shared='us-usamo-2013-4',solution=fix)
add(2014,1,4.5,'Algebra',['Inequalities','Algebraic identities'],r'For real $a,b,c\ge1$, prove $\min\left\{\frac{10a^2-5a+1}{b^2-5b+10},\frac{10b^2-5b+1}{c^2-5c+10},\frac{10c^2-5c+1}{a^2-5a+10}\right\}\le abc$.','Bound the minimum by the geometric mean and rearrange each one-variable ratio. The resulting fifth-degree expression is exactly (a−1)^5, an unobvious but short factorization.',page=3)
add(2014,2,6.5,'Geometry',['Triangle centres','Area & dissection','Geometric inequalities'],r'Let $ABC$ be acute and non-equilateral with $\angle A=60^\circ$, circumcentre $O$, and orthocentre $H$. Prove that line $OH$ meets segments $AB,AC$ at $P,Q$. If $s=[APQ]$ and $t=[BPQC]$, find the set of values of $s/t$.','The 60-degree condition places O,I,H on one auxiliary circle and makes AOMH a rhombus. These facts prove APQ equilateral with side (b+c)/3; an additional side-ratio analysis gives the open range.',page=4)
add(2014,3,7,'Algebra',['Functional equations','Equations & systems'],r'Classify functions $f:\mathbb Z\to\mathbb Z$ satisfying $xf(2f(y)-x)+y^2f(2x-f(y))=f(x)^2/x+f(yf(y))$ for every integer $y$ and every nonzero integer $x$.','A prime-divisibility substitution forces f(0)=0, after which paired x and −x substitutions give the pointwise alternatives 0 and x². Eliminating mixtures requires propagating zeros to even integers and then the odd residue classes.',page=6)
add(2014,4,5,'Number Theory',['Digits & bases','Pigeonhole principle'],r'Fix an integer base $b\ge2$, and write $s_b(n)$ for the sum of the base-$b$ digits of $n$. Prove that infinitely many positive integers have no representation $n+s_b(n)$ with $n\ge1$.','Numbers just below a large power of b have many maximal digits, pushing their images beyond that power. Counting the remaining possible preimages gives arbitrarily many omissions without identifying them.',page=8)
add(2014,5,7.5,'Combinatorics',[],None,'Above target: preventing six in a line uses a three-colour strategy, while forcing five needs a sustained double-threat construction around two protected interior cells. The same problem was assessed at 7.5 in USAMO 2014 Q5.')
add(2014,6,6.5,'Geometry',['Coordinates & vectors','Triangle centres','Circles & tangency'],r'In triangle $ABC$, let $I$ be the incentre, $M,N,P$ the midpoints of $BC,CA,AB$, and $E,F$ the incircle contacts on $CA,AB$. Put $U=EF\cap MN$, $V=EF\cap MP$, and let $X$ be the midpoint of the circumcircle arc $BAC$. Prove that $I$ lies on ray $CV$, and that line $XI$ bisects $UV$.','Coordinates along the A-angle bisector turn EF into a vertical line. The incenter-distance quadratic proves the first collinearity, and explicitly locating the arc midpoint proves the median assertion. This avoids relying on the source’s unproved specialized lemma.',solution=r'''Put $\theta=\angle A/2$, $u=\cos\theta$, $v=\sin\theta$, $b=CA$, $c=AB$, and use coordinates $A=(0,0)$, $B=(cu,cv)$, $C=(bu,-bv)$. Write $I=(i,0)$ and $a=BC$. The angle-bisector formula gives $i=2bc u/(a+b+c)=(b+c-a)/(2u)$, so
$$u i^2-(b+c)i+bc u=0.$$
The contact chord $EF$ is the vertical line $x=iu^2$. Using $MN\parallel AB$ and $MP\parallel AC$ gives
$$U=(iu^2,v(iu-b)),\qquad V=(iu^2,v(c-iu)).$$
The determinant of $V-C$ and $I-C$ is $v[ui^2-(b+c)i+bcu]=0$. Moreover $0<i<bu$ (use $c<a+b$), and $iu^2<i$, so $I$ lies between $C$ and $V$, proving the ray assertion.

The circumcircle through $A,B,C$ has equation $x^2+y^2-\frac{b+c}{2u}x+\frac{b-c}{2v}y=0$. Its other intersection with the internal bisector is $L=((b+c)/(2u),0)$, the midpoint of the arc $BC$ not containing $A$. Its antipode is therefore $X=(0,(c-b)/(2v))$, the required other arc midpoint. At $x=iu^2$, line $IX$ has height $(1-u^2)(c-b)/(2v)=v(c-b)/2$. That point is exactly $(U+V)/2$, completing the proof.''',page=11)
ids={x['id'] for x in new};bank=[x for x in bank if x['id'] not in ids]+new
(R/'data/americas.json').write_text(json.dumps(bank,ensure_ascii=False,indent=2)+'\n')
for y,rr in reviews.items():
 cov['fullyScreened']=[x for x in cov['fullyScreened'] if not(x['competition']=='USAJMO' and x['year']==y)]
 cov['partiallyScreened']=[x for x in cov['partiallyScreened'] if not(x['competition']=='USAJMO' and x['year']==y)]
 cov['fullyScreened'].append(dict(competition='USAJMO',year=y,ratings={n:r['difficulty'] for n,r in rr.items()},source=f'https://web.evanchen.cc/exams/JMO-{y}-notes.pdf',assessmentNotes={n:r['ratingReason'] for n,r in rr.items()}))
cov['papersScreened']=len(cov['fullyScreened']);cov['problemAppearancesScreened']=sum(len(x['ratings']) for x in cov['fullyScreened']+cov['partiallyScreened']);cov['uniqueIncluded']=len(bank)
cov['gaps'][0]='Canada: CMO 2010–2026 and all CJMO 2020–2026 papers fully screened. Official CMO papers exist from 1969, with official worked solutions from 1994; earlier CMO years remain under review.'
cov['gaps'][1]='US: all USAJMO 2010–2026 papers fully screened. USAMO 2015–2025 plus enumerated earlier papers fully screened; USAMO 2026 Q1/Q3 remain unrated for incomplete source proofs. Other historical USAMO papers remain under review.'
